INSERT INTO `comedy_jokes` (`id`, `user_id`, `template_id`, `prompt`, `generated_joke`, `status`, `created_at`, `updated_at`) VALUES
(91, 1, 49, 'cats', '**Feline, condescending, aloof.** \n\n(Imagine the facial expressions and physical awkwardness!) \n', 'active', '2026-04-03 15:41:50', '2026-04-03 15:41:50'),
(92, 1, 47, 'cats', 'Cats: tiny overlords demanding tuna and judgment! 😼\n\n\n\n', 'active', '2026-04-03 15:45:36', '2026-04-03 15:45:36'),
(93, 1, 47, 'work from home', 'My pajamas are my power suit now! 🤯\n\n\n\n---\n\n(Or, if you want a joke)\n\nZoom calls: Where water cooler chit-chat goes to die. 😂\n\n\n\n', 'active', '2026-04-03 16:55:36', '2026-04-03 16:55:36'),
(94, 1, 46, 'breakup stories', 'Clown\'s juggling hearts, one lands in his oversized shoe. \n', 'active', '2026-04-03 17:11:08', '2026-04-03 17:11:08'),
(95, 1, 48, 'joke', 'Why did the scarecrow win an award? \nBecause he was outstanding in his field!\n\n\n\n(Visual: Scarecrow proudly holding a trophy)\n\n\n\n', 'active', '2026-04-03 17:15:56', '2026-04-03 17:15:56'),
(97, 1, 49, 'cats', '“Feline… fluffy… miniature… beast.” \n\nIt’s the combination of trying to be sophisticated and utterly failing that’s the key!', 'active', '2026-04-04 11:28:58', '2026-04-04 11:28:58'),
(98, 1, 1, 'don', 'Don’t like surprises, right? He’s always prepared.', 'active', '2026-04-04 13:06:26', '2026-04-04 13:06:26'),
(99, 1, 1, 'person', 'My grandpa’s dating life…\nHe just keeps saying, “Swipe left!”', 'active', '2026-04-04 13:06:44', '2026-04-04 13:06:44'),
(101, 1, 11, 'cats', 'Okay, here\'s a 2-line podcast riff about cats, under 16 words:\n\n\"Cats are just tiny, furry dictators.\" \n\"Embrace the chaos, it’s purrfectly delightful.\"', 'active', '2026-04-05 11:43:13', '2026-04-05 11:43:13'),
(102, 1, 11, 'cats', 'Okay, here\'s a 2-line podcast riff about cats, under 16 words:\n\n\"Cats are just tiny, furry dictators.\" \n\"Embrace the chaos, it’s purrfectly delightful.\"', 'active', '2026-04-05 11:43:35', '2026-04-05 11:43:35'),
(103, 1, 11, 'cats', 'Okay, here\'s a stand-up joke about cats:\n\n\"You know, I love my cat. Seriously, he\'s amazing. He spends 20 hours a day sleeping, judging me, and occasionally batting at a dust bunny. It’s like having a tiny, furry, judgmental roommate who only communicates in meows and the occasional slow blink.  I’m pretty sure he’s plotting my demise, but hey, at least he’s a *stylish* demise.\"\n\n---\n\nWould you like me to:\n\n*   Try a different type of joke (e.g., observational, one-liner)?\n*   Tailor the joke to a specific cat behavior?', 'active', '2026-04-05 12:11:56', '2026-04-05 12:11:56'),
(104, 1, 11, 'cats', 'Cats are weird, fluffy overlords, honestly.\nJust accept their chaotic, adorable reign.', 'active', '2026-04-05 12:17:39', '2026-04-05 12:17:39'),
(105, 1, 49, 'cats', 'Feline fluffy fellows', 'active', '2026-04-05 12:19:17', '2026-04-05 12:19:17'),
(114, 1, 1, 'cats', 'My cat judges me...\nHe just stares.', 'active', '2026-04-05 22:25:01', '2026-04-05 22:25:01'),
(115, 1, 41, 'cats', 'Cats: masters of napping, judging, and demanding affection.', 'active', '2026-04-05 22:25:09', '2026-04-05 22:25:09'),
(116, 1, 1, 'cats', 'My cat demands a raise in tuna.\nIt claims my salary is just too low.', 'active', '2026-04-06 11:04:39', '2026-04-06 11:04:39'),
(117, 1, 2, 'joke', 'I told a joke about a joke.\nIt had absolutely no punchline, literally.', 'active', '2026-04-06 11:18:46', '2026-04-06 11:18:46'),
(118, 1, 1, 'cats', 'Why don\'t cats make good accountants? They always knock over the numbers.', 'active', '2026-04-06 12:11:05', '2026-04-06 12:11:05'),
(119, 1, 1, 'cats', 'Why did the cat bring a ladder to the party?  \nBecause it heard the food was on the top shelf.', 'active', '2026-04-06 12:11:15', '2026-04-06 12:11:15'),
(120, 1, 1, 'cats', 'Why do cats knock things over?  \nBecause they’re testing if boxes are better than humans at being clumsy.', 'active', '2026-04-06 12:12:42', '2026-04-06 12:12:42'),
(121, 1, 46, 'person', 'Clown\'s oversized shoes trip him, causing a face-plant into a pile of balloons.', 'active', '2026-04-06 18:25:07', '2026-04-06 18:25:07');
INSERT INTO `comedy_templates` (`id`, `category_id`, `name`, `description`, `joke_template`, `init_image`, `preview_image`, `preview_video`, `reference_image`, `is_active`, `usage_count`, `created_at`, `updated_at`) VALUES
(1, 1, 'Black Box Theater', 'Bold and expressive comedian with commanding stage presence', '{\"joke\":\"Generate a 2-line stand-up joke about {input}. STRICT LIMIT: 15 words total. Line 1: Setup. Line 2: Punchline. Output ONLY the 2 lines. No explanations, no prefixes, no meta text.\",\"prompt\":\"A comedian stands on stage, center spotlight. They lean into the microphone and deliver the joke: {input}. Minimal movement, expressive face, slight hand gestures, short pause before punchline. The camera is locked at eye-level in a medium shot. Lighting, framing, and identity remain perfectly consistent throughout.\",\"manual\":\"Keep it under 15 words. Fast setup, sharp punchline.\"}', '/templates/standup/african-female-black-box-theater.jpg', '/templates/standup/african-female-black-box-theater.jpg', NULL, '/public/templates/standup/african-female-black-box-theater-face.png', 1, 0, '2026-03-27 21:40:36', '2026-03-27 21:40:36'),
